<?php
declare(strict_types=1);require __DIR__.'/includes/config.php';require __DIR__.'/includes/live.php';require __DIR__.'/includes/shell.php';
$uid=ir_current_user_id();$ok=ir_table_exists($pdo,'wp_ir2_contacts');
if($ok&&$_SERVER['REQUEST_METHOD']==='POST'){ir_verify_csrf();$a=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($a==='delete'&&$id){$q=$pdo->prepare('DELETE FROM wp_ir2_contacts WHERE id=? AND user_id=?');$q->execute([$id,$uid]);ir_redirect('contacts.php');}$v=[trim((string)($_POST['type']??'chovatel')),trim((string)($_POST['name']??'')),trim((string)($_POST['company']??'')),trim((string)($_POST['email']??'')),trim((string)($_POST['phone']??'')),trim((string)($_POST['address']??'')),trim((string)($_POST['country']??'')),trim((string)($_POST['species']??'')),trim((string)($_POST['notes']??''))];if($v[1]!==''){if($id){$q=$pdo->prepare('UPDATE wp_ir2_contacts SET type=?,name=?,company=?,email=?,phone=?,address=?,country=?,species=?,notes=? WHERE id=? AND user_id=?');$q->execute([...$v,$id,$uid]);}else{$q=$pdo->prepare('INSERT INTO wp_ir2_contacts(user_id,type,name,company,email,phone,address,country,species,notes) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$uid,...$v]);}}ir_redirect('contacts.php');}
$edit=null;$rows=[];if($ok){if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM wp_ir2_contacts WHERE id=? AND user_id=?');$q->execute([(int)$_GET['edit'],$uid]);$edit=$q->fetch()?:null;}$q=$pdo->prepare('SELECT * FROM wp_ir2_contacts WHERE user_id=? ORDER BY name');$q->execute([$uid]);$rows=$q->fetchAll()?:[];}
