<?php if(!$ok):?><section class="panel glow-panel"><div class="empty-state">Databázová tabulka kontaktů chybí. Otevři <a href="upgrade.php"><b>Aktualizaci databáze</b></a> a spusť PATCH 065.</div></section><?php else:?><div class="report-grid"><section class="panel glow-panel"><header class="panel-head"><div><span class="panel-kicker">KONTAKT</span><h2><?=$edit?'Upravit':'Nový kontakt'?></h2></div></header><form method="post" class="form-grid cols-2"><?=ir_csrf_field()?><input type="hidden" name="id" value="<?=ir_e((string)($edit['id']??''))?>"><label>Typ<select name="type"><?php foreach(['chovatel','zákazník','dodavatel','veterinář','laboratoř','přepravce','jiné'] as $x):?><option <?=$x===($edit['type']??'')?'selected':''?>><?=ir_e($x)?></option><?php endforeach?></select></label><label>Jméno / název<input name="name" required value="<?=ir_e($edit['name']??'')?>"></label><label>Firma<input name="company" value="<?=ir_e($edit['company']??'')?>"></label><label>E-mail<input name="email" value="<?=ir_e($edit['email']??'')?>"></label><label>Telefon<input name="phone" value="<?=ir_e($edit['phone']??'')?>"></label><label>Země<input name="country" value="<?=ir_e($edit['country']??'')?>"></label><label class="span-2">Adresa<input name="address" value="<?=ir_e($edit['address']??'')?>"></label><label class="span-2">Druhy / zaměření<input name="species" value="<?=ir_e($edit['species']??'')?>"></label><label class="span-2">Poznámky<textarea name="notes"><?=ir_e($edit['notes']??'')?></textarea></label><button class="btn primary" type="submit">Uložit kontakt</button></form></section><section class="panel glow-panel"><header class="panel-head"><div><span class="panel-kicker">ADRESÁŘ</span><h2><?=count($rows)?> kontaktů</h2></div></header><div class="dashboard-list"><?php foreach($rows as $r):?><div class="dashboard-list-row"><?=ir_visual_icon('profile')?><div><strong><?=ir_e($r['name'])?></strong><small><?=ir_e($r['type'].' · '.$r['email'].' · '.$r['phone'])?></small></div><span><a href="contacts.php?edit=<?=$r['id']?>">Upravit</a></span></div><?php endforeach;if(!$rows):?><p class="empty-state">Zatím žádné kontakty. První kontakt přidej formulářem vlevo.</p><?php endif?></div></section></div><?php endif;ir_page_end();
